// Split into one item per pending person, tagged by delivery channel. Quiet-on-holiday/leave is
// structural here: an empty `pending` array (§5.3's guard already filtered it) yields ZERO items,
// so nothing downstream fires -- there is nothing to special-case.
const body = $input.first().json.body ?? $input.first().json;
const date = body.date;
const pending = Array.isArray(body.pending) ? body.pending : [];
return pending.map((p) => ({
  json: p.hasWaLink && p.waExternalId
    ? { channel: 'wa', tenantId: $env.AGENCY_TENANT_ID, chatId: p.waExternalId, userId: p.userId, date }
    : { channel: 'inapp', tenantId: $env.AGENCY_TENANT_ID, recipientId: p.userId, date },
}));
